-- A second sample client, so the app can be shown with more than one patient.
-- Clinical fields come from record id 17308 of the public Kaggle "Stroke Prediction Dataset"
-- (fedesoriano), which has stroke = 1. The dataset is anonymised, so the name, address, dates
-- and phone numbers are fictional. Like Walter Bennett, she is unassigned until an administrator
-- assigns her to a caregiver or family member in Manage Accounts.
insert into patients (full_name, profile, care_plan)
select 'Eleanor Whitfield', $json${"fullName":"Eleanor Whitfield","dob":"1954-05-09","phone":"(413) 555-0148","strokeType":"Ischemic","strokeDate":"2026-08-31","emergencyName":"Claire Reyes","emergencyRelationship":"Daughter","emergencyPhone":"(413) 555-0192","careProvider":"Dr. Amara Osei, Neurology","recoveryGoals":["Walk around the home safely, first with a walker and then with a cane","Regain use of the right hand for eating, writing and dressing","Speak in full sentences and be easily understood on the phone","Keep blood pressure within the range set by her doctor","Bring blood sugar down with steady meals and a diabetes check-up","Get back to her weekly knitting group with Claire's help"],"address":"37 Linden Street, Springfield, MA 01108","livesWith":"Husband (Harold)","gender":"Female","maritalStatus":"Married","workType":"Private sector","residence":"Urban","hypertension":true,"heartDisease":false,"avgGlucose":221.79,"bmi":30,"smokingStatus":"Never smoked","sampleRecord":true,"datasetSource":"Kaggle Stroke Prediction Dataset (fedesoriano), record id 17308"}$json$::jsonb, $json${"fallRisk":"High","fallPrecautions":["Use the walker every time she walks; move to the cane only when the physical therapist says so","Stand on her weaker (right) side when helping her walk, climb stairs or get in and out of the car","Stand by, close, for bathing and stairs. Use the gait belt for transfers","Rise slowly: sit on the edge of the bed for a minute before standing, to avoid dizziness from blood pressure medicine","Keep the path from bed to bathroom clear and lit at night; remove loose rugs"],"allergies":"No known drug allergies recorded. Confirm with Mrs. Whitfield, her husband and her prescriber before any new medicine.","equipment":["Walker (cane later, when therapy advises)","Shower chair, hand-held shower and grab bars","Raised toilet seat","Gait belt for caregiver-assisted transfers","Upper-arm automatic blood pressure monitor, with a written log","Blood glucose meter and log","Built-up handles for cutlery and a non-slip mat, to help the right hand at meals","Non-slip footwear and night lights","Weekly pill organiser"],"services":[{"name":"Nursing check","detail":"Review the blood pressure and blood glucose logs, medication check, skin check. Report readings outside the range set by the care team.","frequency":"2 visits per week for 6 weeks, then weekly"},{"name":"Blood pressure and blood glucose readings","detail":"Take, and write in the log, before breakfast and in the evening. Sit and rest for 5 minutes before a blood pressure reading.","frequency":"Twice daily"},{"name":"Physical therapy","detail":"Balance, walking, leg and core strength; transfers and safe use of the walker.","frequency":"3 sessions per week"},{"name":"Occupational therapy","detail":"Right hand and arm function, dressing, bathing, cooking and home safety review.","frequency":"2 sessions per week"},{"name":"Speech-language therapy","detail":"Finding words, speech clarity, understanding and swallowing safety. Give her time to answer; do not finish her sentences unless she asks.","frequency":"2 sessions per week"},{"name":"Personal care","detail":"Stand-by help with bathing, dressing and toileting as needed.","frequency":"Daily, mornings"},{"name":"Medication reminders","detail":"Set up the weekly pill organiser and confirm each dose is taken at the same time every day.","frequency":"Daily"},{"name":"Meals","detail":"Low-salt, blood-sugar-friendly meals; plenty of fluids unless the doctor says otherwise.","frequency":"Daily"},{"name":"Daily Strovia check-in","detail":"Rate balance, eyes, face, arms and speech, and note when anything started.","frequency":"Once every day"},{"name":"Transport","detail":"Rides to therapy, clinic and knitting group.","frequency":"As scheduled"}],"medications":["Antiplatelet or blood-thinning medicine to help prevent another stroke","Cholesterol-lowering medicine","Blood pressure medicine: taken at the same time every day, never skipped or stopped without the doctor","Blood-sugar medicine only if the doctor prescribes it after the diabetes check-up","No heart medicines are on record"],"diet":["Low salt (DASH-style) eating: vegetables, fruit, whole grains, lean protein, little processed food","Steady carbohydrate at each meal to keep blood sugar in range; avoid sugary drinks","A gentle weight goal, set together with the doctor once she is stronger. Not a crash diet during recovery","Sit fully upright to eat; small bites and unhurried meals","Use thickened fluids or softer foods only if the speech-language therapist advises"],"followUps":[{"who":"Neurology","when":"Every 4 to 6 weeks in the first 3 months"},{"who":"Primary care (blood pressure)","when":"Within 2 weeks of any hospital stay, then every 3 months"},{"who":"Diabetes check (HbA1c blood test) and review","when":"Within 4 weeks, because her average blood sugar was high"},{"who":"Dietitian","when":"Once, within 6 weeks"},{"who":"Vision check","when":"If any change in vision is noticed"}],"additional":["Her speech is affected. Speak in short, clear sentences, reduce background noise and be patient.","Her daughter Claire lives nearby and is the first family member to call after the office. Her husband Harold is also at home.","Watch for low mood or anxiety, which are common after a stroke, and report changes to the office.","Fatigue is expected. Plan rest between therapy sessions.","Encourage her to do as much as she safely can for herself.","Everyone in the home should know the B.E. F.A.S.T. signs and this plan's emergency steps."],"callOfficeIf":["Any change in symptoms — weakness, numbness, speech or vision that is different from usual but not sudden or severe","A new or worsening symptom flagged by Strovia's daily check-in","A fall, even without injury","Missed or refused medication, or a suspected side effect","Blood pressure or blood sugar readings outside the range set by the care team","Coughing or choking during meals, or a wet-sounding voice after drinking","New swelling, redness or pain in a leg or arm","New confusion, low mood, anxiety or a marked change in sleep or appetite","Skin redness or sores where the person sits or lies","A hospital or emergency visit, new prescription, or any change to this care plan","The regular caregiver cannot attend, or equipment is broken or missing","Swelling, pain or new redness in the right hand or arm after therapy exercises"],"call911If":["Balance — sudden loss of balance, dizziness or trouble walking","Eyes — sudden vision loss or double vision","Face — one side of the face drooping","Arms — sudden weakness or numbness in an arm or leg","Speech — slurred speech, confusion, or trouble understanding","Time — note when it started, then call 911 straight away","A sudden, severe headache unlike any before","A seizure, or the person cannot be woken","Chest pain, or difficulty breathing","Choking that does not clear, or a fall with a head injury or suspected broken bone"],"review":"Every 30 days, and after any change"}$json$::jsonb
